// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

// --- Playtest: "la balle traverse les briques au lieu de rebondir" ---------
//
// The symptom decomposes into seven defects, each with a red test below, each
// trigger computed from the constants of neon.js:
//
//   D1 Face vs coin  — bricks never bounce the ball (only walls/paddle did).
//   D2 Collant       — after a bounce the ball must be out of the brick and
//                      must not re-invert on the next frame.
//   D3 Double inv.   — BRICK_GAP = 8 px < 2*BALL_R = 14 px: a ball on a seam
//                      overlaps two bricks at once; two vy flips cancel.
//   D4 Traversée     — crossing distance BRICK_H + 2*BALL_R = 34 px; max step
//                      ballSpeed(L)*0.05: L5 = 31 px (safe), L6 = 35.5 px
//                      (trigger). Paddle band PADDLE_H + 2*BALL_R = 26 px.
//   D5 Angle mort    — center paddle hit sets vx = 0.6*speed*0 = 0.
//   D6 Vitesse       — launch norm = 1.118*speed; paddle norm = sqrt(1.36).
//   D7 Dépendance dt — discrete collision resolution differs per frame rate.
//
// Discarded with a code-derived reason: Score/combo (bricks are counted once
// via the alive flag set in the same pass, combo resets on paddle touch and on
// life loss; the only gap is the unbounded multiplier, debt #5, a balance
// issue unrelated to traversal) and Transitions (level clear is checked after
// step() on a consistent state, one life lost per exit via the lost flag).

// --- D1. Face vs coin: bricks must bounce the ball -------------------------
test('brick bounce: top face hit flips vy and pushes the ball out', () => {
  const b = brick(100, 100);
  const state = ballState({ x: 136, y: 89, vx: 0, vy: 260 }, { bricks: [b] });
  step(state, 1 / 60);
  assert.equal(state.ball.vy, -260, 'leaves the top face upward');
  assert.equal(state.ball.vx, 0);
  assert.equal(b.alive, false, 'brick broken');
  assert.ok(state.ball.y + BALL_R <= b.y, 'ball ends above the brick, not inside');
  assert.equal(collides(state.ball, b), false, 'no overlap after resolution');
  assert.equal(state.combo, 1);
  assert.equal(state.score, 15); // 10 * comboMultiplier(1)
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(norm - ballSpeed(1)) < 1e-9, 'rebound keeps the level speed');
});

test('brick bounce: left face hit flips vx', () => {
  const b = brick(100, 100);
  const state = ballState({ x: 89, y: 110, vx: 260, vy: 0 }, { bricks: [b] });
  step(state, 1 / 60);
  assert.equal(state.ball.vx, -260);
  assert.equal(state.ball.vy, 0);
  assert.equal(b.alive, false);
  assert.ok(state.ball.x + BALL_R <= b.x, 'ball ends left of the brick');
});

test('brick bounce: corner hit flips both axes', () => {
  const b = brick(100, 100);
  const state = ballState({ x: 89, y: 89, vx: 260, vy: 260 }, { bricks: [b] });
  step(state, 1 / 60);
  assert.equal(state.ball.vx, -260);
  assert.equal(state.ball.vy, -260);
  assert.equal(b.alive, false);
});

// --- D2. Collant: no re-inversion after resolution -------------------------
test('collant: a ball resting on a brick bounces instead of sticking', () => {
  const b = brick(100, 100);
  // Bottom of the ball exactly on the top face of the brick.
  const state = ballState({ x: 136, y: 93, vx: 0, vy: 260 }, { bricks: [b] });
  step(state, 1 / 60);
  assert.equal(state.ball.vy, -260, 'flips exactly once');
  assert.equal(collides(state.ball, b), false, 'ball is out of the rectangle');
  step(state, 1 / 60);
  assert.equal(state.ball.vy, -260, 'no re-inversion on the next step');
  assert.ok(state.ball.y < b.y, 'the ball keeps climbing');
});

// --- D3. Double inversion (seam): one flip per axis per pass ---------------
test('seam: two bricks of the same seam flip vy once, not twice', () => {
  const a = brick(100, 100);
  const b = brick(180, 100); // 8 px gap: a ball on the seam overlaps both
  const state = ballState({ x: 176, y: 89, vx: 0, vy: 260 }, { bricks: [a, b] });
  step(state, 1 / 60);
  assert.equal(state.ball.vy, -260, 'a single vy flip, not two that cancel');
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  assert.equal(state.combo, 2);
  assert.equal(state.score, 35); // 10*1.5 + 10*2
  assert.ok(state.ball.y + BALL_R <= a.y, 'ball bounces back above the row');
});

// --- D4. Traversée (tunneling): no obstacle crossed without a bounce -------
test('tunneling: a step longer than a brick still bounces (level 7)', () => {
  // Max step ballSpeed(7)*0.05 = 40 px > 34 px = BRICK_H + 2*BALL_R: the ball
  // jumps the whole brick in one step without ever overlapping it. The first
  // level where the max step exceeds the crossing distance is 6
  // (710*0.05 = 35.5 > 34): only a swept test catches the pass.
  const b = brick(100, 100);
  const state = ballState({ x: 136, y: 92, vx: 0, vy: 800 }, { level: 7, bricks: [b] });
  const lost = step(state, 0.05);
  assert.equal(lost, false);
  assert.equal(state.ball.vy, -800, 'ball bounces off the brick');
  assert.equal(b.alive, false);
  assert.ok(state.ball.y + BALL_R <= b.y, 'ball is back above the brick');
});

test('tunneling: a fast ball cannot slip through the paddle band', () => {
  // Paddle band PADDLE_H + 2*BALL_R = 26 px; a 30 px step (600 * 0.05) jumps
  // the band entirely: only a swept test catches it.
  const state = ballState({ x: WIDTH / 2, y: PADDLE_Y - BALL_R - 11, vx: 0, vy: 600 });
  const lost = step(state, 0.05);
  assert.equal(lost, false, 'ball must bounce off the paddle, not pass through');
  assert.ok(state.ball.vy < 0, 'ball leaves the paddle upward');
  assert.ok(state.ball.y + BALL_R <= PADDLE_Y, 'ball ends above the paddle');
});

// --- D5. Angle mort: every trajectory stays playable -----------------------
test('dead angle: a center paddle hit never zeroes vx', () => {
  const state = ballState({ x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, vx: 0, vy: 260 });
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0);
  assert.ok(
    Math.abs(state.ball.vx) >= ballSpeed(1) * 0.15,
    'vx clamped to a playable minimum',
  );
});

// --- D6. Vitesse: a rebound flies at the level speed -----------------------
test('vitesse: a paddle rebound flies at the level speed', () => {
  const state = ballState({ x: WIDTH / 2 + 24, y: PADDLE_Y - BALL_R - 2, vx: 0, vy: 260 });
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0);
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
