test('brick bounce: corner hit flips both axes', () => {
  const b = brick(100, 100);
  // Ball at the level speed aiming exactly at the top-left corner: the two
  // slab entry times are equal → corner → BOTH components invert.
  const c = ballSpeed(1) / Math.SQRT2;
  const state = ballState({ x: 90, y: 90, vx: c, vy: c }, { bricks: [b] });
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'both axes inverted');
  assert.ok(
    Math.abs(Math.abs(state.ball.vx) - Math.abs(state.ball.vy)) < 1e-9,
    'symmetric corner rebound',
  );
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(norm - ballSpeed(1)) < 1e-9, 'keeps the level speed');
  assert.equal(b.alive, false);
});

