test('dead angle: a center paddle hit never zeroes vx', () => {
  const state = ballState({ x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, vx: 0, vy: 260 });
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0);
  // The unclamped formula would give vx = 0.6 * speed * hit = 0. The rebound
  // must keep a playable minimum horizontal drift (the clamp guarantees
  // 0.15 * speed; assert well below that to test the invariant, not the
  // implementation constant).
  assert.ok(Math.abs(state.ball.vx) >= ballSpeed(1) * 0.1, 'vx kept away from zero');
});

