let state = createState(1);
let frames = 0, levels = 0, livesLost = 0;
for (let t = 0; t < 300; t += 1/60) {
  const lost = step(state, 1/60);
  if (lost) { livesLost++; state.lives -= 1; state.combo = 0; if (state.lives <= 0) { Object.assign(state, createState(state.level)); } else { state.ball = createState(state.level).ball; } }
  if (state.bricks.every((b) => !b.alive)) { state.level += 1; state.bricks = makeBricks(state.level); state.ball = createState(state.level).ball; levels++; }
  // invariants: never inside a live brick, speed = level speed, ball in field or lost
  for (const b of state.bricks) if (b.alive) assert.equal(collides(state.ball, b), false, 'ball inside a live brick');
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(norm - ballSpeed(state.level)) < 1e-6, 'speed drift');
  assert.ok(state.ball.x - state.ball.r >= -1e-9 && state.ball.x + state.ball.r <= 640 + 1e-9, 'x out of field');
  frames++;
}
console.log('OK — frames:', frames, '| levels cleared:', levels, '| lives lost:', livesLost, '| final level:', state.level, '| score:', state.score);
assert.ok(levels >= 2, 'should have progressed several levels');
"

