import { step, createState, makeBricks, collides, ballSpeed, WIDTH } from './game/neon.js';
import assert from 'node:assert/strict';

let state = createState(1);
let frames = 0, levels = 0, livesLost = 0, minSpeed = Infinity;
for (let t = 0; t < 600; t += 1/60) {
  // dumb AI paddle: chase the ball's x (clamped), like the mouse handler
  state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, state.ball.x - state.paddle.w / 2));
  const lost = step(state, 1/60);
  if (lost) { livesLost++; state.lives -= 1; state.combo = 0; if (state.lives <= 0) { Object.assign(state, createState(state.level)); } else { state.ball = createState(state.level).ball; } }
  if (state.bricks.every((b) => !b.alive)) { state.level += 1; state.bricks = makeBricks(state.level); state.ball = createState(state.level).ball; levels++; }
  for (const b of state.bricks) if (b.alive) assert.equal(collides(state.ball, b), false, 'ball inside a live brick at frame ' + frames);
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  assert.ok(Math.abs(norm - ballSpeed(state.level)) < 1e-6, 'speed drift at frame ' + frames + ': ' + norm);
  assert.ok(state.ball.x - state.ball.r >= -1e-9 && state.ball.x + state.ball.r <= WIDTH + 1e-9, 'x out of field');
  minSpeed = Math.min(minSpeed, norm);
  frames++;
}
console.log('OK — frames:', frames, '| levels cleared:', levels, '| lives lost:', livesLost, '| final level:', state.level, '| score:', state.score, '| min|v|:', minSpeed.toFixed(2));
assert.ok(levels >= 2, 'should have progressed several levels');
assert.ok(livesLost < 10, 'paddle should catch most balls');
"
